@startuml

class GameDesigner {}

class Player {
  + color : string
}

class PlayingPiece {
  + color : string
}

class Game {
  + isGameOver : boolean
}

class Board {
  + layout : string
}

class Tile {
  + isHidden : boolean
  + isActionTile : boolean
  + isVisited : boolean
  + turnsRemaining : int
}

class ConnectionPiece {
  + side : string
}

class ActionCard {
  + type : string
}

class Die {
  + value : int
}

class ActionType {
  ROLL_EXTRA_TURN
  CONNECT_ADJACENT_TILES
  REMOVE_CONNECTION
  MOVE_TO_ARBITRARY_TILE
  LOSE_NEXT_TURN
}

GameDesigner "1" -- "*" Game : designs
Game "1" -- "1" Board : has
Board "1" *-- "*" Tile : contains
Board "1" *-- "*" ConnectionPiece : contains
Board "1" -- "32" ActionCard : contains
Game "1" -- "2..4" Player : involves
Player "1" -- "1" PlayingPiece : has
Game "1" -- "1" Die : uses

Tile "0..1" -- "0..1" Tile : connects
Tile "1" -- "0..1" ConnectionPiece : uses

@enduml

